snippet_css:
:root{
  --bg: #FAF6F0;
  --fg: #5A4A48;
  --muted: #6B5854;
  --surface: #FFFDFA;
  --border: #E4D8D2;
  --accent: #8E5B5B;
  --accent-fg: #FFFFFF;
  --radius: 18px;
  --radius-sm: 12px;
  --shadow: 0 8px 20px rgba(142,91,91,.14);
  --btn-shadow: 0 4px 0 rgba(142,91,91,.28);
  --art-bg: radial-gradient(circle at 40% 70%,#BFD3DC 0 12%,transparent 13%),linear-gradient(160deg,#F7EAE7,#E8C5C1);
  --media-bg: linear-gradient(160deg,#F7EAE7,#E8C5C1);
  --cta-bg: #F7ECE9;
  --input-bg: #FFFFFF;
  --ok: #5E7F62;
  --warn: #A6554B;
  --font-display: 'Playfair Display','Noto Serif TC',serif;
  --font-body: 'Lora','Noto Sans TC',serif;
  --font-mono: 'Courier New',ui-monospace,monospace;
  --focus-ring: var(--accent);
}

